6	/// The shared seam research.md R8 builds because requirements.md §RF10
7	/// already names it (contracts/entries-repository.md). Registered as a
8	/// `get_it` `lazySingleton` so [cachedEntries] survives across modal opens
9	/// (same lifetime pattern as RF03's `VaultRepository`).
10	abstract class EntriesRepository {
11	  Future<Either<Failure, Entry>> create({
12	    required String content,
13	    required EntrySource source,
14	  });
15	
16	  /// FR-011's "local entries store/cache" — in-memory, this process's
17	  /// lifetime. Nothing in this unit ever reads this back out for display;
18	  /// it exists so RF07 has something to read from day one.
19	  List<Entry> get cachedEntries;
20	
21	  /// `GET /entries` (`entries-list`), paginated newest-occurred-first.
22	  /// Retries exactly once through `SessionRepository.refresh()` on
23	  /// `AuthExpiredFailure` before giving up (research.md R4).
24	  Future<Either<Failure, EntriesPage>> list({String? cursor});
