1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/entries/domain/repositories/entries_repository.dart';
5	import 'package:cerne/features/records/domain/entities/entry_merger.dart';
6	import 'package:cerne/features/records/presentation/bloc/records_event.dart';
7	import 'package:cerne/features/records/presentation/bloc/records_state.dart';
8	import 'package:flutter_bloc/flutter_bloc.dart';
9	
10	/// The one bloc behind "Meus Registros" (contracts/records-bloc.md). Depends
11	/// only on `EntriesRepository` — never `SessionRepository`,
12	/// `ConnectivityChecker`, nor `SessionBloc` or any of its event/state types
13	/// (research.md R4/R5/R11, requirements.md RF07's own acceptance criterion).
14	class RecordsBloc extends Bloc<RecordsEvent, RecordsState> {
15	  RecordsBloc({required this._entriesRepository}) : super(const RecordsLoading()) {
16	    on<RecordsStarted>(_onStarted);
17	    on<NextPageRequested>(_onNextPageRequested);
18	    on<PageLoadRetried>(_onPageLoadRetried);
19	    on<RecordsLocalCacheRefreshed>(_onLocalCacheRefreshed);
20	  }
21	
22	  final EntriesRepository _entriesRepository;
23	  final _reauthController = StreamController<void>.broadcast();
24	
25	  /// A one-shot side effect, not a state (research.md R5) —
26	  /// `RecordsPage` listens to this to raise the "Sessão expirada" overlay.
27	  Stream<void> get reauthRequired => _reauthController.stream;
28	
29	  Future<void> _onStarted(RecordsStarted event, Emitter<RecordsState> emit) async {
30	    emit(const RecordsLoading());
31	    await _loadFirstPage(emit);
32	  }
33	
34	  Future<void> _onPageLoadRetried(PageLoadRetried event, Emitter<RecordsState> emit) async {
35	    final current = state;
36	    if (current is RecordsLoadFailure) {
37	      emit(const RecordsLoading());
38	      await _loadFirstPage(emit);
39	    } else if (current is RecordsLoaded && current.pageLoadFailure != null) {
40	      await _fetchNextPage(current, emit);
41	    }
42	  }
43	
44	  Future<void> _loadFirstPage(Emitter<RecordsState> emit) async {
45	    final result = await _entriesRepository.list();
46	    result.match(
47	      (failure) {
48	        if (failure is AuthExpiredFailure) _reauthController.add(null);
49	        emit(RecordsLoadFailure(failure));
50	      },
51	      (page) => emit(
52	        RecordsLoaded(
53	          entries: EntryMerger.merge(
54	            primary: page.entries,
55	            secondary: _entriesRepository.cachedEntries,
56	          ),
57	          nextCursor: page.nextCursor,
58	          isLoadingMore: false,
59	        ),
60	      ),
61	    );
62	  }
63	
64	  Future<void> _onNextPageRequested(
65	    NextPageRequested event,
66	    Emitter<RecordsState> emit,
67	  ) async {
68	    final current = state;
69	    if (current is! RecordsLoaded || current.hasReachedEnd || current.isLoadingMore) {
70	      return;
71	    }
72	    await _fetchNextPage(current, emit);
73	  }
74	
75	  Future<void> _fetchNextPage(RecordsLoaded current, Emitter<RecordsState> emit) async {
76	    emit(
77	      RecordsLoaded(
78	        entries: current.entries,
79	        nextCursor: current.nextCursor,
80	        isLoadingMore: true,
81	      ),
82	    );
83	    final result = await _entriesRepository.list(cursor: current.nextCursor);
84	    result.match(
85	      (failure) {
86	        if (failure is AuthExpiredFailure) {
87	          _reauthController.add(null);
88	          // entries/cursor unchanged, isLoadingMore resets to false, no
89	          // pageLoadFailure — FR-007's "restored exactly as it was" holds
90	          // by construction.
91	          emit(
92	            RecordsLoaded(
93	              entries: current.entries,
94	              nextCursor: current.nextCursor,
95	              isLoadingMore: false,
96	            ),
97	          );
98	        } else {
99	          emit(
100	            RecordsLoaded(
