        const authExpired = AuthExpiredFailure(message: 'expired', requestId: 'r1');
        var callCount = 0;
        when(() => remoteDataSource.getById(any())).thenAnswer((_) async {
          callCount++;
          return callCount == 1 ? const Left(authExpired) : Right(entry);
        });
