    });
  });

  group('funnel button filled state', () {
    testWidgets('hasActiveFilters == true -> funnel renders filled (colorAccent background)', (
      tester,
    ) async {
      await pumpRecordsPage(
        tester,
        RecordsLoaded(
          entries: [_buildEntry(id: 'e1')],
          nextCursor: null,
          isLoadingMore: false,
          dateRange: DateRangeOption.thisWeek,
        ),
      );

