import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  Future<({DateRangeOption dateRange, Set<EntrySource> entryTypes})?> pumpAndOpenSheet(
    WidgetTester tester, {
    DateRangeOption initialDateRange = DateRangeOption.allTime,
    Set<EntrySource> initialEntryTypes = const {},
  }) async {
    ({DateRangeOption dateRange, Set<EntrySource> entryTypes})? result;
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: Builder(
            builder: (context) => ElevatedButton(
              onPressed: () async {
                result = await showModalBottomSheet<
                    ({DateRangeOption dateRange, Set<EntrySource> entryTypes})>(
                  context: context,
                  builder: (_) => FilterSheet(
                    initialDateRange: initialDateRange,
                    initialEntryTypes: initialEntryTypes,
                  ),
                );
              },
              child: const Text('open'),
            ),
          ),
        ),
      ),
    );
    await tester.tap(find.text('open'));
    await tester.pumpAndSettle();
    return Future.value(result);
  }

  testWidgets(
    'select "Esta semana" + "áudio", tap "Aplicar" -> pops with '
    'dateRange: thisWeek, entryTypes: {audio}',
    (tester) async {
      final completer = pumpAndOpenSheet(tester);
      await tester.tap(find.text('Esta semana'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('áudio'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Aplicar'));
      await tester.pumpAndSettle();

      final result = await completer;
      expect(result?.dateRange, DateRangeOption.thisWeek);
      expect(result?.entryTypes, {EntrySource.audio});
    },
  );

  testWidgets('opened with {audio, photo} already applied -> both chips render pre-selected', (
    tester,
  ) async {
    await pumpAndOpenSheet(
      tester,
      initialEntryTypes: const {EntrySource.audio, EntrySource.photo},
    );

    final audioChip = tester.widget<ChoiceChip>(
      find.ancestor(of: find.text('áudio'), matching: find.byType(ChoiceChip)),
    );
    final photoChip = tester.widget<ChoiceChip>(
      find.ancestor(of: find.text('foto'), matching: find.byType(ChoiceChip)),
    );
    expect(audioChip.selected, isTrue);
    expect(photoChip.selected, isTrue);
  });

  testWidgets('selecting a CATEGORIA chip, tapping "Aplicar" -> the popped '
      'result carries no category information at all', (tester) async {
    final completer = pumpAndOpenSheet(tester);
    await tester.tap(find.text('trabalho'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Aplicar'));
    await tester.pumpAndSettle();

    final result = await completer;
    // The record type carries only dateRange/entryTypes — no category field
    // exists to assert on, confirming FR-004 holds by construction.
    expect(result?.dateRange, DateRangeOption.allTime);
    expect(result?.entryTypes, isEmpty);
  });

  testWidgets('selecting several chips, tapping "Limpar" -> all local '
      'selections visually clear; sheet stays open; nothing pops', (tester) async {
    final completer = pumpAndOpenSheet(tester);
    await tester.tap(find.text('Esta semana'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('áudio'));
    await tester.pumpAndSettle();

    await tester.tap(find.text('Limpar'));
    await tester.pumpAndSettle();

    expect(find.byType(FilterSheet), findsOneWidget);
    final dateChip = tester.widget<ChoiceChip>(
      find.ancestor(of: find.text('Esta semana'), matching: find.byType(ChoiceChip)),
    );
    final audioChip = tester.widget<ChoiceChip>(
      find.ancestor(of: find.text('áudio'), matching: find.byType(ChoiceChip)),
    );
    expect(dateChip.selected, isFalse);
    expect(audioChip.selected, isFalse);

    // Dismiss to let the completer resolve, then confirm nothing was popped
    // from the "Limpar" tap itself (the sheet was still open beforehand).
    await tester.tapAt(const Offset(10, 10));
    await tester.pumpAndSettle();
    final result = await completer;
    expect(result, isNull);
  });
}

